from __future__ import annotations

import fnmatch
import os
import re
from collections.abc import Iterable, Sequence
from dataclasses import dataclass, field
from pathlib import Path

SKIP_DIR_NAMES = {
    ".git",
    ".hg",
    ".svn",
    ".venv",
    "venv",
    "node_modules",
    "vendor",
    "dist",
    "build",
    "__pycache__",
    ".tox",
    ".mypy_cache",
    ".pytest_cache",
    ".ruff_cache",
    "target",
    ".idea",
    ".vscode",
}

# Build output and package-manager caches: never source, skipped by name at
# any depth. `scan: include: [".yarn"]` in bizmap.yaml brings one back.
GENERATED_DIR_NAMES = {
    ".yarn",
    ".next",
    ".nuxt",
    ".svelte-kit",
    ".turbo",
    ".cache",
    ".parcel-cache",
    ".output",
    ".vercel",
    ".docusaurus",
    ".expo",
    ".serverless",
    "storybook-static",
}
# Common words that are also build-output folders (`out/`, `coverage/`): only
# skipped next to a project manifest (package.json, go.mod, pyproject.toml…),
# so `internal/coverage/` or `adapters/out/` in source code is still scanned.
ROOT_GENERATED_DIR_NAMES = {"out", "coverage"}
PROJECT_MANIFESTS = (
    "package.json",
    "go.mod",
    "pyproject.toml",
    "setup.py",
    "setup.cfg",
    "requirements.txt",
    "Pipfile",
    "deno.json",
    "tsconfig.json",
)
SKIPPED_PATHS_CAP = 200

# Go: tests, fixtures, mocks and generated code are skipped with the other
# generated files (`scan: skip_generated: false` or `include:` bring them
# back). Generated *data access* code (sqlc, or any generated file that runs
# Exec/Query) is source for BizMap and is always kept.
GO_SKIP_DIR_NAMES = {"testdata", "mocks"}
GO_TEST_GLOBS = ("*_test.go",)
GO_GENERATED_GLOBS = ("*.pb.go", "*.pb.gw.go", "*_mock.go", "mock_*.go", "*_mocks.go")
_GO_GENERATED_HEADER = re.compile(rb"^// Code generated .* DO NOT EDIT\.\s*$", re.M)
_GO_DATA_ACCESS = re.compile(rb"\.(?:Exec|Query|QueryRow|QueryRowx|Queryx|NamedExec)(?:Context)?\(")


def go_generated_kind(path: Path) -> str | None:
    """`"tests"`, `"generated"` or None for a .go file. Generated means a
    `// Code generated … DO NOT EDIT.` line before the package clause, unless
    it is sqlc output or otherwise runs SQL (`.Exec(`, `.QueryContext(`…)."""
    name = path.name
    if any(fnmatch.fnmatch(name, g) for g in GO_TEST_GLOBS):
        return "tests"
    if any(fnmatch.fnmatch(name, g) for g in GO_GENERATED_GLOBS):
        return "generated"
    try:
        with path.open("rb") as fh:
            head = fh.read(4096)
    except OSError:
        return None
    pkg = re.search(rb"^package\s", head, re.M)
    header = head[: pkg.start()] if pkg else head
    if not _GO_GENERATED_HEADER.search(header):
        return None
    if b"generated by sqlc" in header.lower():
        return None
    try:
        body = path.read_bytes()
    except OSError:
        return None
    if _GO_DATA_ACCESS.search(body):
        return None
    return "generated"
GENERATED_FILE_GLOBS = ("*.min.js", "*.min.mjs", "*.min.cjs", "*.bundle.js", "*.chunk.js")
_MINIFY_SUFFIXES = {".js", ".mjs", ".cjs", ".jsx"}
_MINIFY_SAMPLE = 256 * 1024


def looks_generated(path: Path) -> bool:
    """A bundled / minified JS file: a `sourceMappingURL` comment at the end,
    or very long lines (a 2,000+ character line, or 300+ on average)."""
    if path.suffix.lower() not in _MINIFY_SUFFIXES:
        return False
    try:
        with path.open("rb") as fh:
            head = fh.read(_MINIFY_SAMPLE)
            size = fh.seek(0, os.SEEK_END)
            if size > _MINIFY_SAMPLE:
                fh.seek(max(0, size - 1024))
                tail = fh.read()
            else:
                tail = head[-1024:]
    except OSError:
        return False
    if b"sourceMappingURL=" in tail:
        return True
    lines = head.split(b"\n")
    if not lines or len(head) < 2000:
        return False
    longest = max(len(line) for line in lines)
    average = len(head) / len(lines)
    # minifiers drop whitespace; a long hand-written/generated source line
    # (`'a' + 'b' + …`) keeps its spaces
    blanks = sum(head.count(c) for c in (b" ", b"\t", b"\n", b"\r"))
    sparse = blanks / len(head) < 0.06
    return sparse and (longest >= 2000 or average >= 300)


def _glob_regex(pattern: str) -> re.Pattern[str]:
    """A gitignore-style glob (`*`, `?`, `[...]`, `**`) as a regex on a
    `/`-separated relative path."""
    out = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if pattern.startswith("**/", i):
            out.append("(?:.*/)?")
            i += 3
        elif pattern.startswith("/**", i) and i + 3 == len(pattern):
            out.append("/.*")
            i += 3
        elif pattern.startswith("**", i):
            out.append(".*")
            i += 2
        elif c == "*":
            out.append("[^/]*")
            i += 1
        elif c == "?":
            out.append("[^/]")
            i += 1
        elif c == "[":
            j = pattern.find("]", i + 1)
            if j == -1:
                out.append(re.escape(c))
                i += 1
            else:
                body = pattern[i + 1 : j].replace("\\", "\\\\")
                if body.startswith("!"):
                    body = "^" + body[1:]
                out.append(f"[{body}]")
                i = j + 1
        else:
            out.append(re.escape(c))
            i += 1
    return re.compile("".join(out) + r"\Z")


@dataclass
class _IgnoreRule:
    base: str  # directory of the .gitignore, relative to the walk root ("" = root)
    regex: re.Pattern[str]
    negate: bool
    dir_only: bool
    anchored: bool


@dataclass
class GitIgnore:
    """`.gitignore` rules (root and nested files), applied while walking.
    Last matching rule wins; `!pattern` re-includes."""

    rules: list[_IgnoreRule] = field(default_factory=list)

    def load(self, directory: Path, base: str) -> None:
        path = directory / ".gitignore"
        try:
            lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            return
        for raw in lines:
            line = raw.rstrip()
            if not line or line.startswith("#"):
                continue
            negate = line.startswith("!")
            if negate:
                line = line[1:]
            if line.startswith("\\"):
                line = line[1:]
            dir_only = line.endswith("/")
            line = line.rstrip("/")
            if not line:
                continue
            anchored = "/" in line
            line = line.lstrip("/")
            self.rules.append(_IgnoreRule(base, _glob_regex(line), negate, dir_only, anchored))

    def ignored(self, rel_posix: str, is_dir: bool) -> bool:
        verdict = False
        for rule in self.rules:
            if rule.base and not (rel_posix == rule.base or rel_posix.startswith(rule.base + "/")):
                continue
            local = rel_posix[len(rule.base) + 1 :] if rule.base else rel_posix
            if rule.dir_only and not is_dir:
                continue
            target = local if rule.anchored else local.rsplit("/", 1)[-1]
            if rule.regex.match(target):
                verdict = not rule.negate
        return verdict


@dataclass
class WalkOptions:
    """What `iter_files` leaves out besides `exclude` (see bizmap.yaml `scan:`)."""

    include: Sequence[str] = ()  # dir names / globs brought back even if generated or ignored
    gitignore: bool = True
    skip_generated: bool = True
    stats: dict[str, int] = field(default_factory=dict)
    paths: dict[str, list[str]] = field(default_factory=dict)
    _seen: set[tuple[str, str]] = field(default_factory=set, repr=False)

    def bump(self, key: str, rel_posix: str) -> None:
        """Count a skipped path once, however many walks (one per language) see it."""
        if (key, rel_posix) in self._seen:
            return
        self._seen.add((key, rel_posix))
        self.stats[key] = self.stats.get(key, 0) + 1
        self.paths.setdefault(key, []).append(rel_posix)

    def skipped_paths(self) -> dict[str, list[str]]:
        """Skipped paths per reason, sorted, at most SKIPPED_PATHS_CAP each
        (`skipped` has the full counts)."""
        return {k: sorted(v)[:SKIPPED_PATHS_CAP] for k, v in sorted(self.paths.items())}

    def included(self, name: str, rel_posix: str) -> bool:
        return any(name == pat or path_excluded(rel_posix, [pat]) for pat in self.include)


def _gitignore_chain(root: Path) -> list[Path]:
    """`.gitignore` directories from the git work tree root down to ``root``
    (rules above the scanned directory still apply to it)."""
    chain: list[Path] = []
    cur = root
    for parent in [cur, *cur.parents]:
        chain.append(parent)
        if (parent / ".git").exists():
            return list(reversed(chain))
    return [root]


SQL_NAME_PRIORITY = (
    "schema.sql",
    "ddl.sql",
    "init.sql",
)


def path_excluded(rel_posix: str, patterns: Sequence[str] | None) -> bool:
    """Return True if a root-relative path matches any exclude glob.

    Bare prefixes (``cmd/seed``, ``demo/``) match that directory tree.
    ``*`` / ``?`` use fnmatch. ``**`` is treated as a recursive directory glob.
    """
    if not patterns:
        return False
    rel = rel_posix.lstrip("./")
    for raw in patterns:
        pat = str(raw).strip().lstrip("./")
        if not pat:
            continue
        if _match_exclude(rel, pat):
            return True
    return False


def _match_exclude(rel: str, pat: str) -> bool:
    pat_noslash = pat.rstrip("/")
    if rel == pat_noslash or rel.startswith(pat_noslash + "/"):
        if "*" not in pat_noslash and "?" not in pat_noslash and "[" not in pat_noslash:
            return True
    candidates = [pat, pat_noslash]
    if pat.endswith("/") or pat.endswith("/**"):
        prefix = pat.rstrip("/").removesuffix("**").rstrip("/")
        if prefix and (rel == prefix or rel.startswith(prefix + "/")):
            return True
    if pat.startswith("**/"):
        rest = pat[3:]
        if fnmatch.fnmatch(rel, rest) or fnmatch.fnmatch(rel.split("/")[-1], rest):
            return True
        for i, _ in enumerate(rel.split("/")):
            tail = "/".join(rel.split("/")[i:])
            if fnmatch.fnmatch(tail, rest):
                return True
    if "**" in pat:
        prefix, _, suffix = pat.partition("**")
        prefix = prefix.rstrip("/")
        suffix = suffix.lstrip("/")
        if prefix and not (rel == prefix or rel.startswith(prefix + "/")):
            return False
        rest = rel[len(prefix) :].lstrip("/") if prefix else rel
        if not suffix:
            return True
        if fnmatch.fnmatch(rest, suffix) or fnmatch.fnmatch(rest, suffix.lstrip("/")):
            return True
        for i, _ in enumerate(rest.split("/")):
            tail = "/".join(rest.split("/")[i:])
            if fnmatch.fnmatch(tail, suffix):
                return True
        return False
    return any(fnmatch.fnmatch(rel, c) for c in candidates if c)


def iter_files(
    root: Path,
    suffixes: Iterable[str],
    *,
    exclude: Sequence[str] | None = None,
    options: WalkOptions | None = None,
) -> list[Path]:
    """Source files under ``root`` with one of ``suffixes``, sorted. Skips VCS
    and dependency dirs, and by default generated code (build output,
    `.yarn`, coverage, minified/bundled JS) and `.gitignore`d paths."""
    opts = options if options is not None else WalkOptions()
    wanted = {s.lower() if s.startswith(".") else f".{s.lower()}" for s in suffixes}
    go_only = wanted == {".go"}
    out: list[Path] = []
    root = root.resolve()
    ignore = GitIgnore()
    prefix = ""
    if opts.gitignore:
        chain = _gitignore_chain(root)
        top = chain[0]
        for directory in chain[:-1]:
            ignore.load(directory, rel(directory, top) if directory != top else "")
        # every rule base and every tested path is relative to the work-tree root
        prefix = rel(root, top) if root != top else ""
    for dirpath, dirnames, filenames in os.walk(root):
        base = Path(dirpath)
        rel_dir = rel(base, root) if base != root else ""
        if opts.gitignore:
            ignore.load(base, (prefix + "/" + rel_dir).strip("/") if prefix else rel_dir)
        kept: list[str] = []
        for d in sorted(dirnames):
            if d in {".git", ".hg", ".svn"}:
                continue
            d_rel = f"{rel_dir}/{d}" if rel_dir else d
            if opts.include and opts.included(d, d_rel):
                kept.append(d)
                continue
            if d in SKIP_DIR_NAMES:
                continue
            if opts.skip_generated and (
                d in GENERATED_DIR_NAMES
                or (d in ROOT_GENERATED_DIR_NAMES and any(m in filenames for m in PROJECT_MANIFESTS))
            ):
                opts.bump("generated_dirs", d_rel)
                continue
            if opts.skip_generated and go_only and d in GO_SKIP_DIR_NAMES:
                opts.bump("go_test_dirs" if d == "testdata" else "generated_dirs", d_rel)
                continue
            if opts.gitignore and ignore.ignored((prefix + "/" + d_rel).strip("/") if prefix else d_rel, True):
                opts.bump("gitignored", d_rel)
                continue
            kept.append(d)
        dirnames[:] = kept
        for name in filenames:
            path = base / name
            if path.suffix.lower() not in wanted:
                continue
            rel_posix = f"{rel_dir}/{name}" if rel_dir else name
            if path_excluded(rel_posix, exclude):
                continue
            if opts.include and opts.included(name, rel_posix):
                out.append(path)
                continue
            if opts.gitignore and ignore.ignored((prefix + "/" + rel_posix).strip("/") if prefix else rel_posix, False):
                opts.bump("gitignored", rel_posix)
                continue
            if opts.skip_generated and (
                any(fnmatch.fnmatch(name, g) for g in GENERATED_FILE_GLOBS) or looks_generated(path)
            ):
                opts.bump("generated_files", rel_posix)
                continue
            if opts.skip_generated and path.suffix.lower() == ".go":
                kind = go_generated_kind(path)
                if kind is not None:
                    opts.bump("go_tests" if kind == "tests" else "generated_files", rel_posix)
                    continue
            out.append(path)
    return sorted(out)


def rel(path: Path, root: Path) -> str:
    try:
        return path.resolve().relative_to(root.resolve()).as_posix()
    except ValueError:
        return path.as_posix()


def discover_sql_files(
    root: Path, *, exclude: Sequence[str] | None = None, options: WalkOptions | None = None
) -> list[Path]:
    """Return SQL files in apply order: schema-like first, then migrations, then the rest."""
    files = iter_files(root, [".sql"], exclude=exclude, options=options)
    schema_like: list[Path] = []
    migrations: list[Path] = []
    other: list[Path] = []
    for path in files:
        parts = [p.lower() for p in path.parts]
        name = path.name.lower()
        if name in SQL_NAME_PRIORITY or "schema" in parts:
            schema_like.append(path)
        elif "migrations" in parts or "migrate" in parts:
            migrations.append(path)
        else:
            other.append(path)

    def key(path: Path) -> tuple:
        return (path.as_posix().lower(),)

    def schema_key(path: Path) -> tuple:
        name = path.name.lower()
        rank = SQL_NAME_PRIORITY.index(name) if name in SQL_NAME_PRIORITY else 99
        return (rank, path.as_posix().lower())

    schema_like.sort(key=schema_key)
    migrations.sort(key=key)
    other.sort(key=key)
    return schema_like + migrations + other
